<?php
namespace App\Services;use App\Models\MaintenanceRecord;use App\Models\MaintenanceSchedule;use App\Models\MaintenanceType;use App\Models\Vehicle;
class MaintenanceService{public function record(Vehicle $v,MaintenanceType $t,array $d,int $user){$r=MaintenanceRecord::create([...$d,'vehicle_id'=>$v->id,'maintenance_type_id'=>$t->id,'created_by'=>$user]);MaintenanceSchedule::updateOrCreate(['vehicle_id'=>$v->id,'maintenance_type_id'=>$t->id],['next_service_date'=>$t->interval_days?now()->addDays($t->interval_days):null,'next_service_odometer'=>$t->interval_km?$d['odometer']+$t->interval_km:null,'status'=>'UPCOMING']);$v->update(['current_odometer'=>max($v->current_odometer,$d['odometer'])]);return $r;}public function status(MaintenanceSchedule $s):string{$v=$s->vehicle;if(($s->next_service_odometer&&$v->current_odometer>=$s->next_service_odometer)||($s->next_service_date&&today()->greaterThan($s->next_service_date)))return 'OVERDUE';if(($s->next_service_odometer&&$v->current_odometer>=$s->next_service_odometer-500)||($s->next_service_date&&today()->addDays(7)->greaterThanOrEqualTo($s->next_service_date)))return 'DUE_SOON';return 'UPCOMING';}}
